import{_ as a,o as t,c as e,ai as s}from"./chunks/framework.Ai2o9gNv.js";const o="/assets/image-20260214161144031.CrPZt-tH.png",r="/assets/image-20260214161305887.BQJ_HVAX.png",l="/assets/image-20260214161407136.D52E-MUS.png",i="/assets/image-20260214161517684.BffNmVyM.png",m=JSON.parse('{"title":"这可能是程序员离用AI赚钱最容易的一个机会了","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/这可能是程序员离用AI赚钱最容易的一个机会了/这可能是程序员离用AI赚钱最容易的一个机会了.md","filePath":"AI人工智能/这可能是程序员离用AI赚钱最容易的一个机会了/这可能是程序员离用AI赚钱最容易的一个机会了.md","lastUpdated":1772463414000,"__rawMarkdown":"# 这可能是程序员离用AI赚钱最容易的一个机会了\\n\\n## AI发展太快了\\n\\n如果你最近关注科技圈，一定会发现一个趋势：**AI的发展速度已经超出了大多数人的想象**。\\n\\n从ChatGPT的横空出世，到国内各种大模型百花齐放，再到如今AI Agent（智能体）概念的大热，整个行业正在经历一场前所未有的变革。而在这场变革中，字节跳动推出的**扣子（Coze**平台，正在悄然改变着普通人参与AI浪潮的方式。\\n\\n## 什么是扣子（Coze）？\\n\\n扣子是字节跳动推出的新一代一站式AI应用开发平台。它的核心理念是：**让没有编程基础的人也能快速搭建基于大模型的AI应用**。\\n\\n换句话说，你不需要懂代码，不需要理解复杂的模型原理，只需要有想法，就能把AI能力变成一个可用的产品。\\n\\n## 最近刷屏的\\"技能\\"是什么？\\n\\n最近，扣子推出的**Skill（技能）功能**在各大平台刷屏了。那么，什么是技能？\\n\\n简单来说，**技能就是给AI装的专业\\"工具包\\"**。就像给手机装App、给游戏角色装装备一样，技能让AI智能体具备了特定领域的专业能力。\\n\\n举个例子：\\n- 📝 **写作技能**：让AI帮你生成小红书爆款文案\\n- 📊 **PPT技能**：让AI一键生成专业演示文稿\\n- 📈 **数据分析技能**：让AI帮你处理Excel表格、生成图表\\n- 🎨 **设计技能**：让AI帮你完成海报、Logo设计\\n\\n技能可以理解为开发者给Agent写好的「工具包」，让它能做之前做不到的事情。工具包含了做事的方法步骤、需要用到的工具、以及现成的模板资源等。\\n\\n## 程序员的新机会：创建并售卖技能\\n\\n重点来了！**这正是程序员离用AI赚钱最近的一次机会。**\\n\\n扣子平台允许开发者将自己创建的技能**上架到技能商店**，并可以**设置付费**。这意味着：\\n\\n1. **你有技术能力** —— 程序员本身就具备编程思维和开发能力\\n2. **你有创意想法** —— 发现某个场景的痛点，就能转化为技能\\n3. **平台提供变现渠道** —— 上架商店，设置价格，坐等收益\\n\\n![](assets/image-20260214161144031.png)\\n\\n\\n\\n\\n\\n## 我也跟着开发了一些技能，并且上架到应用商店了\\n\\n动手能力强的小伙伴也可以动手去操作一下，我也开发了几个技能，上架到技能商店上了。\\n\\n![](assets/image-20260214161305887.png)\\n\\n这两天看了一下，也有了第一笔收入，还是挺开心的。\\n\\n![](assets/image-20260214161407136.png)\\n\\n![](assets/image-20260214161517684.png)\\n\\n### 欢迎体验\\n\\nhttps://www.coze.cn/?skills=7602185684891303999\\n\\n\\n\\n\\n\\n\\n\\n## 参考链接\\n\\n1. https://www.coze.cn/skills?tab=space\\n\\n\\n\\n"}'),p={name:"AI人工智能/这可能是程序员离用AI赚钱最容易的一个机会了/这可能是程序员离用AI赚钱最容易的一个机会了.md"};function g(c,n,_,A,h,I){return t(),e("div",null,[...n[0]||(n[0]=[s('<h1 id="这可能是程序员离用ai赚钱最容易的一个机会了" tabindex="-1">这可能是程序员离用AI赚钱最容易的一个机会了 <a class="header-anchor" href="#这可能是程序员离用ai赚钱最容易的一个机会了" aria-label="Permalink to &quot;这可能是程序员离用AI赚钱最容易的一个机会了&quot;">​</a></h1><h2 id="ai发展太快了" tabindex="-1">AI发展太快了 <a class="header-anchor" href="#ai发展太快了" aria-label="Permalink to &quot;AI发展太快了&quot;">​</a></h2><p>如果你最近关注科技圈，一定会发现一个趋势：<strong>AI的发展速度已经超出了大多数人的想象</strong>。</p><p>从ChatGPT的横空出世，到国内各种大模型百花齐放，再到如今AI Agent（智能体）概念的大热，整个行业正在经历一场前所未有的变革。而在这场变革中，字节跳动推出的<strong>扣子（Coze</strong>平台，正在悄然改变着普通人参与AI浪潮的方式。</p><h2 id="什么是扣子-coze" tabindex="-1">什么是扣子（Coze）？ <a class="header-anchor" href="#什么是扣子-coze" aria-label="Permalink to &quot;什么是扣子（Coze）？&quot;">​</a></h2><p>扣子是字节跳动推出的新一代一站式AI应用开发平台。它的核心理念是：<strong>让没有编程基础的人也能快速搭建基于大模型的AI应用</strong>。</p><p>换句话说，你不需要懂代码，不需要理解复杂的模型原理，只需要有想法，就能把AI能力变成一个可用的产品。</p><h2 id="最近刷屏的-技能-是什么" tabindex="-1">最近刷屏的&quot;技能&quot;是什么？ <a class="header-anchor" href="#最近刷屏的-技能-是什么" aria-label="Permalink to &quot;最近刷屏的&quot;技能&quot;是什么？&quot;">​</a></h2><p>最近，扣子推出的<strong>Skill（技能）功能</strong>在各大平台刷屏了。那么，什么是技能？</p><p>简单来说，<strong>技能就是给AI装的专业&quot;工具包&quot;</strong>。就像给手机装App、给游戏角色装装备一样，技能让AI智能体具备了特定领域的专业能力。</p><p>举个例子：</p><ul><li>📝 <strong>写作技能</strong>：让AI帮你生成小红书爆款文案</li><li>📊 <strong>PPT技能</strong>：让AI一键生成专业演示文稿</li><li>📈 <strong>数据分析技能</strong>：让AI帮你处理Excel表格、生成图表</li><li>🎨 <strong>设计技能</strong>：让AI帮你完成海报、Logo设计</li></ul><p>技能可以理解为开发者给Agent写好的「工具包」，让它能做之前做不到的事情。工具包含了做事的方法步骤、需要用到的工具、以及现成的模板资源等。</p><h2 id="程序员的新机会-创建并售卖技能" tabindex="-1">程序员的新机会：创建并售卖技能 <a class="header-anchor" href="#程序员的新机会-创建并售卖技能" aria-label="Permalink to &quot;程序员的新机会：创建并售卖技能&quot;">​</a></h2><p>重点来了！<strong>这正是程序员离用AI赚钱最近的一次机会。</strong></p><p>扣子平台允许开发者将自己创建的技能<strong>上架到技能商店</strong>，并可以<strong>设置付费</strong>。这意味着：</p><ol><li><strong>你有技术能力</strong> —— 程序员本身就具备编程思维和开发能力</li><li><strong>你有创意想法</strong> —— 发现某个场景的痛点，就能转化为技能</li><li><strong>平台提供变现渠道</strong> —— 上架商店，设置价格，坐等收益</li></ol><p><img src="'+o+'" alt=""></p><h2 id="我也跟着开发了一些技能-并且上架到应用商店了" tabindex="-1">我也跟着开发了一些技能，并且上架到应用商店了 <a class="header-anchor" href="#我也跟着开发了一些技能-并且上架到应用商店了" aria-label="Permalink to &quot;我也跟着开发了一些技能，并且上架到应用商店了&quot;">​</a></h2><p>动手能力强的小伙伴也可以动手去操作一下，我也开发了几个技能，上架到技能商店上了。</p><p><img src="'+r+'" alt=""></p><p>这两天看了一下，也有了第一笔收入，还是挺开心的。</p><p><img src="'+l+'" alt=""></p><p><img src="'+i+'" alt=""></p><h3 id="欢迎体验" tabindex="-1">欢迎体验 <a class="header-anchor" href="#欢迎体验" aria-label="Permalink to &quot;欢迎体验&quot;">​</a></h3><p><a href="https://www.coze.cn/?skills=7602185684891303999" target="_blank" rel="noreferrer">https://www.coze.cn/?skills=7602185684891303999</a></p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ol><li><a href="https://www.coze.cn/skills?tab=space" target="_blank" rel="noreferrer">https://www.coze.cn/skills?tab=space</a></li></ol>',28)])])}const u=a(p,[["render",g]]);export{m as __pageData,u as default};
